import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"Platform compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/compatibility.md","filePath":"en/shitbot/compatibility.md"}'),o={name:"en/shitbot/compatibility.md"};function i(n,t,s,l,c,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="platform-compatibility" tabindex="-1">Platform compatibility <a class="header-anchor" href="#platform-compatibility" aria-label="Permalink to &quot;Platform compatibility&quot;">​</a></h1><h2 id="platforms-and-java" tabindex="-1">Platforms and Java <a class="header-anchor" href="#platforms-and-java" aria-label="Permalink to &quot;Platforms and Java&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Runs on</th><th>Minimum plugin Java</th><th>Main purpose</th></tr></thead><tbody><tr><td>ShitBotSpigot</td><td>Bukkit servers such as Spigot, Paper, Folia, and CatServer</td><td>8</td><td>Standalone server or Bukkit backend behind a proxy</td></tr><tr><td>ShitBotBungee</td><td>BungeeCord</td><td>8</td><td>Network proxy, OneBot, cross-server forwarding, and backend commands</td></tr><tr><td>ShitBotVelocity</td><td>Velocity</td><td>21</td><td>Network proxy, OneBot, cross-server forwarding, and backend commands</td></tr><tr><td>ShitBotNukkit</td><td>Nukkit-MOT</td><td>17</td><td>Standalone Nukkit-MOT server</td></tr></tbody></table><p>The server software may require a newer Java version. For example, ShitBotSpigot&#39;s Java 8 compatibility does not mean modern Paper can run on Java 8.</p><h2 id="recorded-environments" tabindex="-1">Recorded environments <a class="header-anchor" href="#recorded-environments" aria-label="Permalink to &quot;Recorded environments&quot;">​</a></h2><p>The repository documents adaptation or verification for these environments:</p><ul><li>Spigot 1.8.8.</li><li>Spigot 1.12.2.</li><li>Paper 1.21.</li><li>Paper 1.21.11.</li><li>Paper 26.1.</li><li>Folia 1.21.11.</li><li>CatServer 1.12.2.</li><li>BungeeCord <code>26.1-R0.1-SNAPSHOT</code> builds.</li><li>Multiple Velocity versions.</li><li>Nukkit-MOT; the module&#39;s documented compile dependency is <code>1.26.40-R1</code>.</li></ul><p>These records do not guarantee identical behavior for every server fork, plugin combination, or modded hybrid environment. Report the exact server software, version, and complete startup log for compatibility problems.</p><h2 id="feature-differences" tabindex="-1">Feature differences <a class="header-anchor" href="#feature-differences" aria-label="Permalink to &quot;Feature differences&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Spigot standalone</th><th>Spigot backend</th><th>BungeeCord / Velocity</th><th>Nukkit-MOT</th></tr></thead><tbody><tr><td>Direct OneBot connection</td><td>Yes</td><td>No</td><td>Yes</td><td>Yes</td></tr><tr><td>Binding check on login</td><td>Yes</td><td>Yes</td><td>At the proxy</td><td>Yes</td></tr><tr><td>Chat forwarding</td><td>Yes</td><td>Handled by proxy</td><td>Yes</td><td>Text and URLs</td></tr><tr><td>Save live inventory snapshots</td><td>Yes</td><td>Yes</td><td>Cannot read live inventories directly</td><td>Yes</td></tr><tr><td>Render inventories from a shared database</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Built-in profile card and online time</td><td>Yes</td><td>Does not record backend sessions</td><td>Yes</td><td>Yes</td></tr><tr><td>Proxy/backend command channel</td><td>Can act as backend</td><td>Listens for proxy requests</td><td>Dispatches to backends</td><td>Not used</td></tr><tr><td>PictureBridge media markers</td><td>Yes</td><td>Depends on proxy message entry</td><td>Yes</td><td>Not used</td></tr><tr><td>Advanced Java2D scenes</td><td>Yes</td><td>Can supply backend data</td><td>Yes</td><td>Yes, without Bukkit PAPI</td></tr><tr><td>PlaceholderAPI template data</td><td>Resolve locally</td><td>Resolve proxy requests</td><td>Forward to selected Spigot backend</td><td>Not supported</td></tr></tbody></table><p>Backend Spigot instances do not connect to OneBot, avoiding duplicate QQ replies from the proxy and backend.</p><h2 id="folia" tabindex="-1">Folia <a class="header-anchor" href="#folia" aria-label="Permalink to &quot;Folia&quot;">​</a></h2><p>The Spigot descriptor declares <code>folia-supported: true</code>. Inventory fields are copied on Bukkit&#39;s main thread or the player&#39;s region thread on Folia. Database operations, resource scanning, and rendering run asynchronously.</p><p>Other plugins that modify inventories, permissions, or logs through methods unsafe for Folia can still affect integrations.</p><h2 id="optional-dependencies" tabindex="-1">Optional dependencies <a class="header-anchor" href="#optional-dependencies" aria-label="Permalink to &quot;Optional dependencies&quot;">​</a></h2><p>Basic operation does not require these plugins, but they extend permissions or data sources:</p><table tabindex="0"><thead><tr><th>Plugin</th><th>Platform</th><th>Purpose</th></tr></thead><tbody><tr><td>LuckPerms</td><td>Spigot, BungeeCord, Velocity, Nukkit-MOT</td><td>Offline character permissions</td></tr><tr><td>Vault</td><td>Spigot</td><td>Offline permissions when LuckPerms is unavailable</td></tr><tr><td>Essentials / EssentialsX</td><td>Spigot</td><td>Preferred source of server TPS data</td></tr><tr><td>PlaceholderAPI</td><td>Spigot</td><td>Batched placeholder resolution for advanced templates explicitly declaring <code>papi</code></td></tr></tbody></table><p>Without optional permission plugins, online players still use platform permissions, but offline permission checks are limited.</p><h2 id="onebot" tabindex="-1">OneBot <a class="header-anchor" href="#onebot" aria-label="Permalink to &quot;OneBot&quot;">​</a></h2><p>ShitBot uses OneBot v11 forward WebSocket. The implementation must support:</p><ul><li>Group message events.</li><li>Sending group messages.</li><li>Image message segments.</li><li>Action responses.</li><li>The <code>Authorization: Bearer</code> header when using access-token authentication.</li></ul><p>Fields for files, video, voice, share cards, and temporary media URLs vary between implementations. ShitBot converts them to in-game labels where possible; if no URL is available, it shows the available summary.</p><h2 id="picturebridge" tabindex="-1">PictureBridge <a class="header-anchor" href="#picturebridge" aria-label="Permalink to &quot;PictureBridge&quot;">​</a></h2><p>Java players can install the separate <a href="https://github.com/hutuyee/PictureBridge" target="_blank" rel="noreferrer">PictureBridge</a> client mod when using <code>forwarding.group-to-game.media-mode: &quot;picturebridge&quot;</code>.</p><p>PictureBridge is not bundled in ShitBot&#39;s server JAR. Nukkit-MOT does not use this client protocol.</p>',25)])])}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
